import json, html, pathlib, os, runpy, shutil
P=pathlib.Path(__file__).parent
D=P/'dist'
ORIGIN=os.environ.get('SITE_URL', 'https://endpoint-directory.radod.chatgpt.site').rstrip('/')
# Rebuild derived data and copy authored assets for a clean checkout.
runpy.run_path(str(P/'scripts/import_catalogs.py'), run_name='__main__')
D.mkdir(exist_ok=True)
for asset in (P/'assets').iterdir():
 if asset.is_file(): shutil.copy2(asset,D/asset.name)
E=html.escape
# Remove only generated HTML so removed records cannot remain as stale pages.
for generated in D.rglob('*.html'):generated.unlink()
apis=json.loads((P/'catalog.json').read_text())
checks_path=P/'sources/link-checks.json'
link_checks=json.loads(checks_path.read_text())['results'] if checks_path.exists() else {}
excluded=[]
for a in apis:
 a['link_status']=link_checks.get(a['slug'],{}).get('status')
 if a['review']=='catalog' and a['link_status'] in (404,410):excluded.append(a['slug'])
apis=[a for a in apis if a['slug'] not in excluded]
(P/'sources/excluded-broken-links.json').write_text(json.dumps(excluded,indent=2))
(P/'apis.json').write_text(json.dumps(apis,ensure_ascii=False,indent=2))
categories=list(dict.fromkeys(a['category'] for a in apis))
cs={'Weather':'weather','Finance':'finance','Development':'development','Entertainment':'entertainment','Geography':'geography','Books & culture':'books-culture','Food & drink':'food-drink','Science':'science','Music & audio':'music-audio','Utilities':'utilities','Language':'language'}
ci={'Weather':'☀','Finance':'↗','Development':'⌘','Entertainment':'▷','Geography':'◎','Books & culture':'▤','Food & drink':'♧','Science':'⌬','Music & audio':'♫','Utilities':'◇','Language':'Aa'}
intro={'Weather':'Compare weather APIs for forecasts and current conditions. Pay attention to commercial-use restrictions and whether a key is required.','Finance':'Find exchange-rate and economic-data APIs. Reference currency rates, historical stock prices, and economic indicators serve different purposes.','Development':'Build and test interfaces with placeholder data. These APIs simulate a backend; writes generally do not persist.','Entertainment':'Explore APIs for games, television, photos, and news. Check content rights separately from API access permissions.','Geography':'Find country reference data for location-aware applications. Use current endpoints and confirm authentication requirements.','Books & culture':'Discover book and museum APIs. Check image rights and fair-use policies before displaying content in a public product.','Food & drink':'Prototype with recipe and ingredient APIs. Shared test keys are useful for development, but production access can require an upgrade.','Science':'Explore space and Earth science data. Preserve observation times, credits, and context when presenting results.'}
intro.update({'Music & audio':'Explore radio station streams and podcast catalog APIs. Check audio rights, caching guidance, and stream availability before building a player.','Utilities':'Find small APIs for public holidays and connection diagnostics. Confirm regional date coverage and understand which device makes each request.','Language':'Explore word-finding APIs for rhymes, autocomplete, and language games. Check vocabulary coverage and upcoming access changes.'})
intro['Development']='Prototype interfaces with mock products, posts, and user profiles. Keep test data separate from real customer records; simulated writes may not persist.'
intro['Food & drink']='Explore recipes, drink ingredients, and barcode-based food products. Access, attribution, and production-use conditions differ by provider.'
intro['Science']='Find astronomy, earthquake, biodiversity, and scholarly metadata APIs. Preserve observation dates, source credits, and the limits of each dataset.'
import re,math,unicodedata
for c in categories:
 intro[c]=f'Explore {c.lower()} APIs with provider links and reported access requirements. Community imports are marked separately from documentation-reviewed guides.'
 cs.setdefault(c,re.sub(r'[^a-z0-9]+','-',unicodedata.normalize('NFKD',c).encode('ascii','ignore').decode().lower()).strip('-'))
 ci.setdefault(c,'◇')
 intro.setdefault(c,f'Explore {c.lower()} APIs with provider links and reported access requirements. Community imports are marked separately from our documentation-reviewed guides.')
categories=sorted(categories,key=str.casefold)
PAGE_SIZE=36
reviewed_count=sum(a['review']=='reviewed' for a in apis)
def card(a):
 return f'''<article class="api-card" data-slug="{a['slug']}"><div class="card-top"><span class="api-mark {a['color']}" aria-hidden="true">{E(a['mark'])}</span><span class="tag">{E(a['category'])}</span></div><h3><a href="/apis/{a['slug']}/">{E(a['name'])}</a><span aria-hidden="true">↗</span></h3><p>{E(a['description'])}</p><div class="review-badge {a['review']}">{'Docs reviewed' if a['review']=='reviewed' else 'Catalog import · not reviewed'}</div><div class="card-bottom"><span class="auth {'no-key' if a['auth']=='No key' else ''}">{'Reported: ' if a['review']=='catalog' else ''}{E(a['auth'])}</span><span>{E(a['plan'])}</span></div></article>'''
def nav():return '<header><div class="nav-inner"><a class="brand" href="/" aria-label="Endpoint home"><span class="brand-icon">e<span>.</span></span>endpoint<span class="brand-dot">.</span></a><nav aria-label="Main"><a href="/" class="nav-browse">Explore APIs</a><a href="/collections/no-api-key/">No-key collection</a><a href="/about/">How we curate ↗</a></nav></div></header>'
def footer():return '<footer><a class="brand" href="/">endpoint.</a><p>A good starting point for your next build.</p><a href="/about/">Sources & editorial policy</a><span>Independent directory · 2026</span></footer>'
def sidebar(active=''):
 return '<aside class="sidebar"><div class="aside-label">THE DIRECTORY</div><a class="category '+('active' if not active else '')+'" href="/"><span>▦ &nbsp; All APIs</span><span>'+str(len(apis))+'</span></a><label class="category-search"><span class="sr-only">Find a category</span><input id="category-search" type="search" placeholder="Find a category…"></label><div class="category-scroll">'+''.join(f'<a class="category {"active" if active==c else ""}" href="/categories/{cs[c]}/"><span><i aria-hidden="true">{ci[c]}</i>{E(c)}</span><span>{sum(a["category"]==c for a in apis)}</span></a>' for c in categories)+'</div><p id="category-empty" hidden>No matching categories.</p><div class="sidebar-note"><span class="tiny-mark">{ }</span><h3>Prefer a closer look?</h3><p>Start with guides checked against provider documentation.</p><a href="/collections/docs-reviewed/">Browse reviewed guides ↗</a></div></aside>'
def schema(data):return '<script type="application/ld+json">'+json.dumps(data,ensure_ascii=False).replace('<','\\u003c')+'</script>'
def page(path,title,description,body,data=None,indexable=True):
 canonical=ORIGIN+path
 robots='' if indexable else '<meta name="robots" content="noindex,follow">'
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | Endpoint</title><meta name="description" content="{E(description)}"><link rel="canonical" href="{canonical}">{robots}<meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='11' fill='%231a443c'/%3E%3Ctext x='8' y='29' font-family='Arial' font-size='30' font-weight='bold' fill='white'%3Ee%3C/text%3E%3Ccircle cx='31' cy='29' r='3' fill='%23ddfb9a'/%3E%3C/svg%3E"><link rel="stylesheet" href="/styles.css"><script defer src="/app.js"></script>{schema(data) if data else ''}</head><body><a href="#main" class="skip-link">Skip to content</a>{nav()}{body}{footer()}<div id="toast" role="status"></div></body></html>'''
 target=D/path.strip('/')/'index.html' if path!='/' else D/'index.html'
 target.parent.mkdir(parents=True,exist_ok=True);target.write_text(doc)
 if indexable:paths.append(path)
paths=[]
def pagination(base,total,current):
 def href(n):return base if n==1 else base+'page/'+str(n)+'/'
 count=max(1,math.ceil(total/PAGE_SIZE))
 numbers=sorted(set([1,count]+list(range(max(1,current-2),min(count,current+2)+1))))
 out=[];prev=0
 if current>1:out.append(f'<a href="{href(current-1)}" data-page="{current-1}" aria-label="Previous page">←</a>')
 for n in numbers:
  if n-prev>1:out.append('<span aria-hidden="true">…</span>')
  out.append(f'<a href="{href(n)}" data-page="{n}" '+('aria-current="page"' if n==current else '')+f'>{n}</a>');prev=n
 if current<count:out.append(f'<a href="{href(current+1)}" data-page="{current+1}" aria-label="Next page">→</a>')
 return ''.join(out)
def directory(path,title,desc,items,active='',root=False):
 total_pages=max(1,math.ceil(len(items)/PAGE_SIZE))
 slim=[{k:a[k] for k in ['slug','name','category','mark','color','description','auth','plan','review']} for a in items]
 catalog_json=json.dumps(slim,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
 for current in range(1,total_pages+1):
  selected=items[(current-1)*PAGE_SIZE:current*PAGE_SIZE]
  actual_path=path if current==1 else path+'page/'+str(current)+'/'
  stamp=f'<div class="directory-stamp"><strong>{len(apis):,}</strong><span>APIs to explore</span><div>{len(categories)} categories · {reviewed_count} reviewed guides</div></div>'
  hero=f'''<section class="intro"><div class="eyebrow"><span class="slash">/</span> THE DEVELOPER’S DIRECTORY</div><div class="intro-row"><div><h1>{'Good APIs.<br><span>Less digging.</span>' if root else E(title)}</h1><p>{E(desc)}</p></div>{stamp if root else ''}</div></section>'''
  search='''<form class="search-form" role="search"><span class="search-symbol" aria-hidden="true">⌕</span><label class="sr-only" for="search">Search APIs</label><input id="search" name="q" type="search" placeholder="What are you building? Search APIs, topics, or use cases…" autocomplete="off"><kbd>/</kbd><button type="submit">Find an API →</button></form>'''
  filters='''<div class="filters"><span>Quick filters</span><button class="filter-chip" data-filter="No key" aria-pressed="false">⌁ No API key</button><button class="filter-chip" data-filter="Free access" aria-pressed="false">Free access</button><button class="filter-chip" data-filter="Development" aria-pressed="false">For prototyping</button><button class="filter-chip" data-filter="reviewed" aria-pressed="false">Docs reviewed</button><button id="clear" class="clear" hidden>Clear filters ×</button></div>'''
  grid=''.join(card(a) for a in selected)
  note=f'<p class="catalog-note">{reviewed_count} guides checked against provider docs. Community imports show reported details; current access and pricing still need confirmation. <a href="/about/">About the sources</a></p>'
  body=f'<main id="main" class="shell">{hero}{search}{filters}<div class="directory-layout">{sidebar(active)}<div class="results">{note}<div class="results-heading"><h2>{E("Explore the directory" if root else title)} <span id="result-count">{len(items)}</span></h2><label class="sort-label">Sort by <select id="sort"><option value="curated">Curated order</option><option value="name">Name: A–Z</option></select></label></div><p id="page-summary" class="page-summary">Showing {(current-1)*PAGE_SIZE+1}–{min(current*PAGE_SIZE,len(items))} of {len(items):,}</p><div id="api-grid" class="api-grid" data-base="{path}" data-initial-page="{current}">{grid}</div><div id="empty" class="empty" hidden><h3>No matching APIs yet.</h3><p>Try a broader search or clear a filter.</p><button id="reset-empty">Reset search & filters</button></div><nav id="pagination" class="pagination" aria-label="Results pages">{pagination(path,len(items),current)}</nav><p class="review-note">Catalog snapshot: 16 Sep 2026 · Documentation link checks are not API uptime tests.</p><script id="catalog-data" type="application/json">{catalog_json}</script></div></div></main>'
  data={'@context':'https://schema.org','@type':'CollectionPage','name':title,'description':desc,'url':ORIGIN+actual_path,'mainEntity':{'@type':'ItemList','numberOfItems':len(selected),'itemListElement':[{'@type':'ListItem','position':(current-1)*PAGE_SIZE+i+1,'name':a['name'],'url':ORIGIN+'/apis/'+a['slug']+'/'} for i,a in enumerate(selected)]}}
  page(actual_path,title+(f' — page {current}' if current>1 else ''),desc,body,data)
def imported_detail(a):
 sources=''.join(f'<li><a href="{E(s["url"])}" target="_blank" rel="noopener noreferrer">{E(s["name"])}</a></li>' for s in a['sources'])
 status=a.get('link_status')
 linktext='The documentation server responded successfully to a HEAD request.' if status and 200<=status<400 else 'The documentation link could not be confirmed automatically. This does not establish whether the API is available.'
 body=f'''<main id="main" class="shell detail"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Directory</a><span>/</span><a href="/categories/{cs[a['category']]}/">{E(a['category'])}</a><span>/</span><span>{E(a['name'])}</span></nav><div class="detail-top"><span class="api-mark large {a['color']}">{E(a['mark'])}</span><div><div class="eyebrow">COMMUNITY CATALOG ENTRY</div><h1>{E(a['name'])}</h1><p>{E(a['description'])}</p></div><a class="primary-link" href="{E(a['docs'])}" target="_blank" rel="noopener noreferrer">Provider / documentation ↗</a></div><article class="catalog-detail"><div class="facts"><div><span>REPORTED AUTH</span><strong>{E(a['auth'])}</strong></div><div><span>PRICING</span><strong>Not verified</strong></div><div><span>REVIEW STATUS</span><strong>Catalog import</strong></div></div><h2>Check with the provider</h2><p>{E(a['note'])}</p><p>This entry links to a provider resource. It does not include a checked request example or an endorsement.</p><h2>Catalog details</h2><dl class="catalog-facts"><dt>Category</dt><dd>{E(a['category'])}</dd><dt>HTTPS (reported)</dt><dd>{E(a['reported_https'])}</dd><dt>CORS (reported)</dt><dd>{E(a['reported_cors'])}</dd><dt>Imported</dt><dd>16 September 2026</dd></dl><h2>Documentation link check</h2><p>{linktext} This is not a live endpoint or pricing check.</p><h2>Sources</h2><ul>{sources}</ul><p>Community data is reused under the source projects’ MIT licenses. <a href="/about/">Read our attribution and review policy.</a></p><a class="primary-link" href="/categories/{cs[a['category']]}/">More {E(a['category'].lower())} APIs →</a></article></main>'''
 page('/apis/'+a['slug']+'/',a['name']+' API — documentation & reported access',a['description']+' Community catalog entry; current access and pricing are unverified.',body,indexable=False)
directory('/','Public APIs for developers','Find your next building block. Search public API catalogs and reviewed guides, with clear source labels and links to the providers.',apis,root=True)
for c in categories:directory('/categories/'+cs[c]+'/',c+' APIs',intro[c],[a for a in apis if a['category']==c],c)
directory('/collections/no-api-key/','APIs with no key reported','Find APIs listed as requiring no key. Community entries are source-reported; reviewed guides include individual usage notes. Confirm current provider requirements.',[a for a in apis if a['auth']=='No key'])
directory('/collections/docs-reviewed/','Documentation-reviewed APIs','Start with individually researched guides, usage restrictions, and copyable examples. Documentation review is not continuous endpoint monitoring.',[a for a in apis if a['review']=='reviewed'])
for a in apis:
 if a['review']!='reviewed':
  imported_detail(a)
  continue
 curl='curl '+json.dumps(a['endpoint'])+(' \\\n  -H '+json.dumps(a['header']) if a['header'] else '')
 headers=dict([a['header'].split(': ',1)]) if a['header'] else {}
 opts=', {\n  headers: '+json.dumps(headers)+'\n}' if headers else ''
 js='const response = await fetch(\n  '+json.dumps(a['endpoint'])+opts+'\n);\nif (!response.ok) throw new Error(`HTTP ${response.status}`);\nconst data = await response.json();\nconsole.log(data);'
 related=[x for x in apis if x['category']==a['category'] and x['slug']!=a['slug']][:3]
 if not related:related=[x for x in apis if x['auth']==a['auth'] and x['slug']!=a['slug']][:3]
 body=f'''<main id="main" class="shell detail"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Directory</a><span>/</span><a href="/categories/{cs[a['category']]}/">{E(a['category'])}</a><span>/</span><span>{E(a['name'])}</span></nav><div class="detail-top"><span class="api-mark large {a['color']}">{E(a['mark'])}</span><div><div class="eyebrow">{E(a['category'])} API</div><h1>{E(a['name'])}</h1><p>{E(a['description'])}</p></div><a class="primary-link" href="{a['docs']}" target="_blank" rel="noopener noreferrer">Official documentation ↗</a></div><div class="detail-columns"><article><div class="facts"><div><span>AUTHENTICATION</span><strong>{a['auth']}</strong></div><div><span>FREE ACCESS</span><strong>{a['plan']}</strong></div><div><span>SOURCE REVIEWED</span><strong>16 Sep 2026</strong></div></div><h2>What you could build</h2><p>{E(a['use'])}</p><div class="usage-note"><h2>Know before you build</h2><p>{E(a['note'])}</p><a href="{a['docs']}" target="_blank" rel="noopener noreferrer">Check current provider documentation ↗</a></div><h2>Make your first request</h2><p>{'Replace YOUR_API_KEY with your own provider key. Keep production keys on your server.' if 'YOUR_API_KEY' in curl else 'This is a starter request, not a live response. Check the provider’s usage conditions above.'}</p><div class="code-panel"><div class="code-header"><span>cURL</span><button class="copy" data-copy="curl-code">Copy request</button></div><pre><code id="curl-code">{E(curl)}</code></pre></div><div class="code-panel"><div class="code-header"><span>{"JavaScript · server-side" if a["header"].startswith("User-Agent:") else "JavaScript"}</span><button class="copy" data-copy="js-code">Copy code</button></div><pre><code id="js-code">{E(js)}</code></pre></div></article><aside class="detail-aside"><div class="eyebrow">IN THIS CATEGORY</div><h2>Keep exploring.</h2><p>Find another building block for your project.</p>{''.join(card(x) for x in related)}</aside></div></main>'''
 page('/apis/'+a['slug']+'/',a['name']+' API: free access, authentication & examples',a['description']+' '+a['auth']+'. '+a['plan']+'. Usage notes and request examples.',body,{'@context':'https://schema.org','@type':'TechArticle','headline':a['name']+' API guide','description':a['description'],'dateModified':'2026-09-16','url':ORIGIN+'/apis/'+a['slug']+'/','citation':a['docs']})
page('/about/','How Endpoint curates APIs','Our editorial approach to API access requirements, free plans, source links, and examples.',f'''<main id="main" class="shell prose"><div class="eyebrow">ABOUT THE DIRECTORY</div><h1>A shortlist with<br>the fine print included.</h1><p class="lead">Endpoint helps developers find an API, understand the access conditions, and make a first request.</p><h2>What is in the directory?</h2><p>{len(apis)} public APIs across {len(categories)} categories. The original 32 guides include documentation reviews and request examples. Expanded community listings link to provider resources and show reported authentication, HTTPS, and CORS information. They do not contain invented code examples or verified-pricing claims.</p><h2>What do the labels mean?</h2><dl><dt>No key</dt><dd>The listed public endpoint does not require a private API key. Rate limits and terms still apply.</dd><dt>Catalog import</dt><dd>Details are reported by an external catalog and may be outdated. Confirm access and pricing with the provider. “Check pricing” does not mean a free plan was verified.</dd><dt>API key</dt><dd>Registration or a provider credential is needed. A limited demo key may be available.</dd><dt>Test key</dt><dd>The example uses a shared development key. This does not imply unrestricted production access.</dd><dt>Free access / Free tier</dt><dd>A free public service or a free allowance exists, subject to the provider’s limits. It is not a promise of unlimited use.</dd><dt>Noncommercial / Development only</dt><dd>The free option has purpose restrictions. A commercial or production deployment may need a paid plan.</dd></dl><h2>Catalog imports and attribution</h2><p>Community entries are imported from <a href="https://github.com/public-apis/public-apis">public-apis/public-apis</a> and <a href="https://github.com/public-api-lists/public-api-lists">public-api-lists/public-api-lists</a>. Both catalogs are MIT-licensed. <a href="/licenses/public-apis.txt">Public APIs license</a> · <a href="/licenses/public-api-lists.txt">Public API Lists license</a>.</p><p>Duplicates are consolidated; catalog-only documentation links returning HTTP 404 or 410 are excluded. Timeouts and access blocks remain unconfirmed rather than being described as defunct. Import dates do not imply individual verification. A successful documentation HEAD request does not establish API health, pricing, or current terms.</p><p>Unreviewed detail pages remain browsable but are excluded from search indexing. Category pages and reviewed guides form the searchable editorial core.</p><h2>Sources and updates</h2><p>The initial listings were researched from official provider documentation on 16 September 2026. This is a documentation review, not continuous endpoint testing. Always check current provider terms before depending on an API.</p><h2>Ordering and independence</h2><p>Curated order is an editorial starting point, not a popularity ranking. There are no paid placements or fabricated reviews in this edition. Endpoint is not affiliated with the listed providers.</p><h2>Your privacy</h2><p>This edition does not collect accounts, newsletter signups, or API keys. Search and filters run in your browser, and examples are not executed by the directory. Opening provider links takes you to services with their own privacy policies. The hosting platform may process standard access logs.</p><a class="primary-link" href="/">Explore the directory →</a></main>''')
page('/404/','Page not found','This page could not be found in the Endpoint API directory.','<main id="main" class="shell prose"><div class="eyebrow">404</div><h1>No endpoint here.</h1><p>Try the directory to find the API you need.</p><a class="primary-link" href="/">Back to all APIs →</a></main>')
(D/'404.html').write_text((D/'404/index.html').read_text())
(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+ORIGIN+p+'</loc><lastmod>2026-09-16</lastmod></url>' for p in paths if p!='/404/')+'</urlset>')
(D/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
(D/'licenses').mkdir(exist_ok=True)
for name in ['public-apis','public-api-lists']:(D/'licenses'/f'{name}.txt').write_text((P/'sources'/f'{name}-license.txt').read_text())
print(f'Generated {len(list(D.rglob('*.html')))} HTML files, {len(paths)} indexable pages, {len(apis)} API listings and {len(categories)} categories.')
